import json, sys
r=json.load(open(sys.argv[1]))
print("PRODUCT:", json.dumps(r["product"])[:400])
print("VERDICT:", r["verdict"]); print("MENTIONS:", r["mentions"], "SURFACES", [(s["key"],s["status"],s["n"]) for s in r["surfaces"]])
for b in r["board"]: print("BOARD", b["key"], b["status"], "|", b["line1"], "|", b["line2"])
S=r["sentiment"]; print("SENT", S["score"], S["delta30"], S["trend_word"], "prev",S["score_prev"], "last30",S["score_last30"], "n",S["n_labeled"], "retail", S["retail"], "spark", S["spark"])
for c in S["clusters"]: print(" CLUSTER",c["rank"],repr(c["title"]),"|",c["category"],c["mentions"],c["trend"],c["trend_pct"],c["sources"]); print("    quote:",c["quote"]); print("    ev:",[ (e["source"],e["title"][:55]) for e in c["evidence"]][:6])
print("PRAISES",S["praises"])
Pr=r["price"]; print("PRICE walmart",Pr["walmart"],"median",Pr["median_start"],"->",Pr["median_now"],Pr["median_change_pct"],"range",Pr["range"],"nobs",Pr["n_observations"],"nmerch",Pr["n_merchants"],Pr["walmart_position"]); print(" headline",Pr["headline"])
for m in Pr["series"]["merchants"]: print("  M",m["name"],m["long_tail"],m["points"][:3],"oos",m["oos_from_day"])
for e in Pr["events"]: print("  EV",e["n"],e["date"],e["label"],e["kind"],e["url"][:50])
print(" amazon_history", Pr.get("amazon_history"))
L=r["listings"]; print("LISTINGS",L["headline"],L["range"]); print(" ticks",L["ticks"]); print(" chips",L["chips"])
for row in L["rows"]: print("  ROW",row["merchant"],row["price"],row.get("price_note"),row["stock"],row["first_seen"],row["long_tail"],row["seller"],row["url"][:60])
D=r["dupes"]; print("DUPES exact",[(d["id"],d["title"][:60]) for d in D["exact"]]); print(" other",[(d["id"],d["kind"],d["title"][:40]) for d in D["other"]])
R=r["recall"]; print("RECALL",R["model_level"]["status"],R["model_level"]["headline"], "items",R["model_level"]["items"], "fam", [(f["product"][:50], f["date"], f["url"][-40:]) for f in R["brand_family"]], "scan", R["complaint_scan"])
print("COST", r["cost"])
